const item = $input.first().json;
const body = item.body || item;
const lead = body.lead || body;

function s(v, max) {
  if (v === undefined || v === null) return null;
  let str = String(v).trim();
  if (max) str = str.slice(0, max);
  return str.length ? str : null;
}

function cyrb53Hash(str) {
  let h1 = 0xdeadbeef ^ str.length, h2 = 0x41c6ce57 ^ str.length;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);
}

const name = s(lead.name, 200);
const email = s(lead.email, 320);
const phone = s(lead.phone, 40);

const errors = [];
if (!name) errors.push('name is required');
if (!email && !phone) errors.push('email or phone is required');
if (!lead.cleaningType && !lead.serviceType) errors.push('service type is required');

const toInt = (v, lo, hi) => {
  const n = Number(v);
  if (!Number.isFinite(n)) return null;
  return Math.max(lo, Math.min(hi, Math.round(n)));
};
const toNum = (v, lo, hi) => {
  const n = Number(v);
  if (!Number.isFinite(n)) return null;
  return Math.max(lo, Math.min(hi, n));
};

const bedrooms = toInt(lead.bedrooms, 0, 20);
const bathrooms = toInt(lead.bathrooms, 0, 20);
const propertySize = toNum(lead.propertySizeSqm, 0, 100000);
const estimatedQuote = toNum(body.estimatedQuoteAud, 0, 1000000);

let extras = [];
if (Array.isArray(lead.extras)) {
  extras = lead.extras.map((e) => s(e, 100)).filter(Boolean).slice(0, 20);
}

let preferredDate = null;
if (lead.preferredDate) {
  const d = new Date(lead.preferredDate);
  if (!isNaN(d.getTime())) preferredDate = d.toISOString().slice(0, 10);
}

const utm = body.utm || {};
const headers = item.headers || {};
const ipRaw = headers['cf-connecting-ip'] || headers['x-forwarded-for'] || '';
const ip = String(ipRaw).split(',')[0].trim();
const ipHash = ip ? cyrb53Hash(ip + '|kquality-website-quote-salt') : null;
const userAgent = s(headers['user-agent'], 500);

return [{
  json: {
    valid: errors.length === 0,
    errors,
    name,
    email,
    phone,
    company: s(lead.company, 200),
    propertyType: s(lead.propertyType, 100),
    bedrooms,
    bathrooms,
    propertySize,
    serviceType: s(lead.cleaningType || lead.serviceType, 100),
    extras,
    preferredDate,
    message: s(lead.notes || lead.message, 2000),
    estimatedQuote,
    source: s(body.source, 100) || 'website',
    utmSource: s(utm.source, 200),
    utmMedium: s(utm.medium, 200),
    utmCampaign: s(utm.campaign, 200),
    utmTerm: s(utm.term, 200),
    utmContent: s(utm.content, 200),
    ipHash,
    userAgent,
    raw: body
  }
}];

